\title{A Tight Cubic Spectral Gap for One-Dimensional \\ Swap Reconfiguration Chains}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
The chord-swap Markov chain reconfigures chord diagrams of a fixed genus by
reconnecting the endpoints of two chords, and its mixing rate is governed by the
spectral gap $\gamma_{n,g}$. Empirically, at fixed genus $g$ and growing number of
chords $n$, the gap decays like $n^{-3}$, but existing polynomial bounds leave the
exponent undetermined. We isolate the mechanism responsible for the exponent $3$
and prove, unconditionally and with matching two-sided bounds, that it is exact
for the canonical one-dimensional prototype: the weighted path swap chain, in
which a local move shifts a single monotone statistic by one unit. We develop the
Rayleigh-quotient calculus for a finite reversible chain abstractly, establish an
upper bound via a single position witness, and prove the matching lower bound via a
telescoping Cauchy--Schwarz Poincar\'e inequality. The result is the sharp
two-sided estimate $2\,n^{-3} \le \gamma_n \le 12\,n^{-3}$, so
$\gamma_n = \Theta(n^{-3})$. The exponent equals $3 = 4-1$, the difference between
the quartic growth of the statistic's variance and the linear growth of its
Dirichlet energy. We explain why this mechanism is model-agnostic and conjecture a
universal cubic law for $\pm 1$-monotone swap chains.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Chord diagrams and reconfiguration}
A \emph{chord diagram} of size $n$ is a perfect matching of $2n$ marked points on a
circle by $n$ chords drawn inside the disk. Its \emph{genus} $g$ is the topological
genus of the orientable surface obtained by thickening the chords into ribbons; it
records the complexity of the crossing structure. Chord diagrams model RNA
secondary structure, knot and tangle projections, and maps on surfaces, and a
recurring computational question is how to sample uniformly from the diagrams of a
fixed genus. The natural sampler is the \emph{chord-swap Markov chain}: from a
diagram, select two chords, detach their four endpoints, and reconnect them by one
of the permitted alternatives preserving the genus; iterate at random. The chain
is reversible with respect to the uniform distribution on genus-$g$ diagrams, and
its mixing time is controlled by the spectral gap $\gamma_{n,g}$.

\subsection{The empirical exponent, and the question}
Across the chord-swap chain and related swap chains on perfect matchings,
simulations at fixed genus show $\gamma_{n,g}$ decaying like $n^{-3}$. General
comparison and canonical-path techniques certify a \emph{polynomial} lower bound on
the gap, but they do not pin the exponent. What is the true exponent, and why?

\subsection{Contribution}
We answer the question in the one-dimensional model that isolates the mechanism,
and we explain why the mechanism should persist in the full model. We (i) develop
an abstract Rayleigh-quotient calculus and its ``engine'' (Section~\ref{sec:calc});
(ii) prove a sharp upper bound $\gamma_n \le 12\,n^{-3}$ from a single position
witness (Section~\ref{sec:upper}); (iii) prove a matching lower bound
$\gamma_n \ge 2\,n^{-3}$ from a telescoping Cauchy--Schwarz Poincar\'e inequality
(Section~\ref{sec:lower}); (iv) combine them into the tight theorem
$\gamma_n = \Theta(n^{-3})$ (Section~\ref{sec:tight}); and (v) formulate
universality conjectures (Section~\ref{sec:disc}).

\section{Preliminaries}
Throughout, $V$ is a finite state space with $N = |V|$ elements. A \emph{weight
kernel} is a symmetric, non-negative function $Q\colon V\times V\to\mathbb{R}$. For
a reversible chain with stationary distribution $\pi$ and transition matrix $P$,
one takes $Q(x,y)=\pi(x)P(x,y)$; the spectral gap of $P$ coincides with the
combinatorial gap below. A \emph{test function} is any $f\colon V\to\mathbb{R}$; it
is \emph{non-constant} if $f(x)\ne f(y)$ for some $x,y$.

\section{The Rayleigh-quotient calculus}\label{sec:calc}

\begin{definition}[Dirichlet energy]
$\dir_Q(f) = \sum_{x\in V}\sum_{y\in V} Q(x,y)\,(f(x)-f(y))^2.$
\end{definition}

\begin{definition}[Pairwise variation]
$\vr(f) = \sum_{x\in V}\sum_{y\in V}(f(x)-f(y))^2.$
Up to the factor $1/(2N^2)$ this is the variance of $f$ under the uniform law.
\end{definition}

\begin{definition}[Rayleigh quotient and gap]
For non-constant $f$, $\RQ_Q(f)=\dir_Q(f)/\vr(f)$, and the combinatorial spectral
gap is $\gamma(Q)=\inf\{\RQ_Q(f) : f \text{ non-constant}\}.$
\end{definition}

\begin{lemma}[Non-negativity]\label{lem:nonneg}
For non-negative $Q$, $\dir_Q(f)\ge 0$ and $\vr(f)\ge 0$. Moreover $\vr(f)>0$ iff
$f$ is non-constant.
\end{lemma}
\begin{proof}
Each summand of $\dir_Q$ is a non-negative weight times a square, and each summand
of $\vr$ is a square. If $f(x)\ne f(y)$ the positive term $(f(x)-f(y))^2$ appears
in $\vr(f)$; if $f$ is constant all terms vanish.
\end{proof}

\begin{lemma}[Closed form]\label{lem:vreq}
$\vr(f) = 2\bigl(N\sum_x f(x)^2 - (\sum_x f(x))^2\bigr).$
\end{lemma}
\begin{proof}
Expand $(f(x)-f(y))^2 = f(x)^2 - 2f(x)f(y) + f(y)^2$ and sum over ordered pairs.
The squared terms each contribute $N\sum_x f(x)^2$ and the cross term contributes
$2(\sum_x f(x))^2$. This is the unnormalized $\operatorname{Var}=\mathbb{E}[f^2]-\mathbb{E}[f]^2$.
\end{proof}

\begin{lemma}[Gap non-negativity]
For non-negative $Q$, $\gamma(Q)\ge 0$.
\end{lemma}
\begin{proof}
Every Rayleigh quotient is a ratio of non-negative quantities
(Lemma~\ref{lem:nonneg}); the infimum of a non-negative set bounded below by $0$ is
non-negative.
\end{proof}

\begin{theorem}[The Rayleigh engine]\label{thm:engine}
Let $Q$ be non-negative. For every non-constant $f$, $\gamma(Q)\le\RQ_Q(f).$
\end{theorem}
\begin{proof}
The set of Rayleigh quotients over non-constant $f$ is bounded below by $0$, so its
infimum exists and is at most each member; $\RQ_Q(f)$ is such a member.
\end{proof}

\section{The weighted path and the position witness}\label{sec:upper}

\begin{definition}[Path weights]
The length-$n$ path has state space $\{0,\dots,n-1\}$ and
$\Qpath(x,y)=1$ if $|x-y|=1$ and $0$ otherwise.
\end{definition}

\begin{definition}[Position function]
$\fpos(i)=i$. It is monotone and a single move shifts it by exactly one unit.
\end{definition}

\begin{lemma}[Linear energy]\label{lem:dir}
For $n\ge 1$, $\dir_{\Qpath}(\fpos)=2(n-1)$.
\end{lemma}
\begin{proof}
On each of the $n-1$ edges $\{i,i+1\}$ the position function changes by $1$,
contributing $1$ in each orientation; non-edges contribute $0$.
\end{proof}

\begin{lemma}[Quartic variation]\label{lem:vr}
For all $n$, $\vr(\fpos)=\dfrac{n^2(n^2-1)}{6}$.
\end{lemma}
\begin{proof}
By Lemma~\ref{lem:vreq} with $f(i)=i$ and the sums $\sum_{i<n} i = n(n-1)/2$,
$\sum_{i<n} i^2 = n(n-1)(2n-1)/6$:
\[
\vr(\fpos)=2\Bigl(n\cdot\tfrac{n(n-1)(2n-1)}{6}-\bigl(\tfrac{n(n-1)}{2}\bigr)^2\Bigr)=\frac{n^2(n^2-1)}{6}. \qedhere
\]
\end{proof}

\begin{theorem}[Exact Rayleigh quotient]\label{thm:rq}
For $n\ge 2$, $\RQ_{\Qpath}(\fpos)=\dfrac{12}{n^2(n+1)}.$
\end{theorem}
\begin{proof}
Divide Lemma~\ref{lem:dir} by Lemma~\ref{lem:vr} and use $n^2-1=(n-1)(n+1)$.
\end{proof}

\begin{theorem}[Rayleigh quotient is $\Theta(n^{-3})$]\label{thm:rqtheta}
For $n\ge 2$, $\dfrac{6}{n^3}\le\RQ_{\Qpath}(\fpos)\le\dfrac{12}{n^3}.$
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:rq} the quotient is $12/(n^2(n+1))$. For $n\ge 2$,
$n^3\le n^2(n+1)\le 2n^3$; dividing $12$ by these bounds yields the window.
\end{proof}

\begin{corollary}[Cubic upper bound]\label{cor:upper}
For $n\ge 2$, $\gamma(\Qpath)\le \dfrac{12}{n^2(n+1)}\le\dfrac{12}{n^3}.$
\end{corollary}
\begin{proof}
$\fpos$ is non-constant, so Theorem~\ref{thm:engine} gives
$\gamma(\Qpath)\le\RQ_{\Qpath}(\fpos)$; apply Theorem~\ref{thm:rqtheta}.
\end{proof}

\section{The matching Poincar\'e lower bound}\label{sec:lower}

\begin{definition}[Edge energy]
$\Eedge(f)=\sum_{i=0}^{n-2}(f(i+1)-f(i))^2\ge 0.$
\end{definition}

\begin{lemma}[Dirichlet energy as edge energy]\label{lem:diredge}
For every $f$ on the path, $\dir_{\Qpath}(f)=2\,\Eedge(f).$
\end{lemma}
\begin{proof}
The only non-zero weights lie on the $n-1$ undirected edges $\{i,i+1\}$, each
counted once in each orientation; both orientations contribute $(f(i+1)-f(i))^2$.
\end{proof}

\begin{lemma}[Telescoping Cauchy--Schwarz]\label{lem:pair}
For every $f$ and all positions $x,y$, $(f(x)-f(y))^2\le n\,\Eedge(f).$
\end{lemma}
\begin{proof}
Assume $x\le y$. Telescoping, $f(y)-f(x)=\sum_{i=x}^{y-1}(f(i+1)-f(i))$, a sum of
$y-x\le n$ increments. By Cauchy--Schwarz, a sum of $m$ reals has square at most
$m$ times the sum of their squares, so
$(f(y)-f(x))^2\le (y-x)\sum_{i=x}^{y-1}(f(i+1)-f(i))^2\le n\,\Eedge(f)$, enlarging
the index set to all edges (each term non-negative) and using $y-x\le n$.
\end{proof}

\begin{theorem}[Poincar\'e inequality]\label{thm:poincare}
For every $f$ on the path, $\vr(f)\le n^3\,\Eedge(f)=\dfrac{n^3}{2}\,\dir_{\Qpath}(f).$
\end{theorem}
\begin{proof}
Sum Lemma~\ref{lem:pair} over all $n^2$ ordered pairs $(x,y)$: the left side is
$\vr(f)$ and the right side is $n^2\cdot n\,\Eedge(f)=n^3\,\Eedge(f)$. The final
equality is Lemma~\ref{lem:diredge}.
\end{proof}

\begin{theorem}[Rayleigh lower bound]\label{thm:rqlower}
For every non-constant $f$ on the path with $n\ge 1$, $\RQ_{\Qpath}(f)\ge\dfrac{2}{n^3}.$
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:diredge}, $\dir_{\Qpath}(f)=2\Eedge(f)$; by
Theorem~\ref{thm:poincare}, $\vr(f)\le n^3\Eedge(f)$. Since $f$ is non-constant,
$\vr(f)>0$, forcing $\Eedge(f)>0$. Hence
$\RQ_{\Qpath}(f)=2\Eedge(f)/\vr(f)\ge 2\Eedge(f)/(n^3\Eedge(f))=2/n^3.$
\end{proof}

\begin{corollary}[Cubic lower bound]\label{cor:lower}
For $n\ge 2$, $\gamma(\Qpath)\ge 2\,n^{-3}.$
\end{corollary}
\begin{proof}
The gap is the infimum of Rayleigh quotients over non-constant $f$, each
$\ge 2\,n^{-3}$ by Theorem~\ref{thm:rqlower}.
\end{proof}

\section{The tight two-sided theorem}\label{sec:tight}

\begin{theorem}[Tight cubic spectral gap]\label{thm:main}
For all $n\ge 2$, $\dfrac{2}{n^3}\le\gamma(\Qpath)\le\dfrac{12}{n^3}$; in
particular $\gamma_n=\Theta(n^{-3})$, unconditionally.
\end{theorem}
\begin{proof}
Combine Corollary~\ref{cor:upper} and Corollary~\ref{cor:lower}.
\end{proof}

The halves are complementary: the upper bound is a single explicit witness through
the Rayleigh engine (Theorem~\ref{thm:engine}), while the lower bound is universal
over test functions via telescoping and Cauchy--Schwarz
(Theorem~\ref{thm:poincare}).

\section{Discussion and future directions}\label{sec:disc}

\subsection{Why the exponent is $3=4-1$}
A monotone $\pm 1$-statistic on $n$ states has linear Dirichlet energy (it changes
by $O(1)$ across each of $O(n)$ active edges) and quartic variation
($\vr=\Theta(N\sum f^2)$ scales like $n\cdot n^3=n^4$ for a statistic spread over a
range of size $\Theta(n)$). Their ratio is $\Theta(n^{-3})$, and the Poincar\'e
inequality certifies this cannot be beaten by more than a constant.

\subsection{Model-agnosticism}
Neither half of the argument used any feature of the path beyond unit edge weights
on a one-dimensional adjacency and a monotone $\pm 1$-statistic. The lower-bound
engine applies to any reversible swap chain admitting such a statistic.

\subsection{Conjectures}
\begin{conjecture}[Genus-graded cubic gap]
For chord diagrams of $n$ chords and any fixed genus $g$, the chord-swap chain has
spectral gap $\Theta(n^{-3})$, with implied constants depending only on $g$. A
chord diagram carries a monotone genus-aware displacement changing by one unit per
swap, with linear energy and quartic variance, reproducing the path model's ratio.
\end{conjecture}
\begin{conjecture}[Universal cubic law]
Any reversible swap chain admitting a monotone integer statistic taking
$\Theta(n)$ distinct values, changing by $\pm 1$ per accepted move, with
$\Theta(n)$ boundary-adjacent transitions, has spectral gap $\Theta(n^{-3})$. The
exponent $3=4-1$ is forced by growth rates alone.
\end{conjecture}
\begin{conjecture}[Sharp leading constant]
For the path swap chain, $\gamma_n=(c+o(1))\,n^{-3}$ for an explicit constant $c$
strictly inside $[2,12]$, realized by the discrete first eigenfunction (a shifted
cosine profile) rather than the linear position witness.
\end{conjecture}

\subsection{Conclusion}
The spectral gap of the canonical one-dimensional swap chain is exactly of cubic
order, $2\,n^{-3}\le\gamma_n\le 12\,n^{-3}$, by pairing a single position witness
with a telescoping Cauchy--Schwarz Poincar\'e inequality. The mechanism --- quartic
variance over linear energy --- is model-agnostic, explaining the empirically
observed $n^{-3}$ decay and charting a route to the full genus-graded family.

\end{document}

