"""Verify the exact closed forms for the position witness on the path."""
from __future__ import annotations
from typing import Callable, List


def path_weight(x: int, y: int) -> float:
    return 1.0 if abs(x - y) == 1 else 0.0


def dirichlet_energy(weight: Callable[[int, int], float], f: List[float]) -> float:
    n = len(f)
    return sum(weight(x, y) * (f[x] - f[y]) ** 2 for x in range(n) for y in range(n))


def pairwise_variation(f: List[float]) -> float:
    n = len(f)
    return sum((f[x] - f[y]) ** 2 for x in range(n) for y in range(n))


def report(n: int) -> None:
    f = [float(i) for i in range(n)]
    d = dirichlet_energy(path_weight, f)
    v = pairwise_variation(f)
    rq = d / v
    print(f"n={n:>4}: dir={d:.0f} (=2(n-1)={2*(n-1)}), "
          f"vr={v:.0f} (=n^2(n^2-1)/6={n**2*(n**2-1)//6}), "
          f"RQ={rq:.3e} (=12/(n^2(n+1))={12/(n**2*(n+1)):.3e})")


if __name__ == "__main__":
    for n in (2, 4, 8, 16, 32, 64):
        report(n)

"""Empirically confirm the Poincare inequality vr(f) <= n^3 * edge_energy(f)
and the Rayleigh lower bound RQ(f) >= 2/n^3 over many random test functions."""
from __future__ import annotations
import random
from typing import List


def edge_energy(f: List[float]) -> float:
    return sum((f[i + 1] - f[i]) ** 2 for i in range(len(f) - 1))


def pairwise_variation(f: List[float]) -> float:
    n = len(f)
    return sum((f[x] - f[y]) ** 2 for x in range(n) for y in range(n))


def rayleigh(f: List[float]) -> float:
    # dir on the path = 2 * edge_energy.
    return 2.0 * edge_energy(f) / pairwise_variation(f)


def stress_test(n: int, trials: int, seed: int = 0) -> None:
    rng = random.Random(seed)
    min_rq, worst = float("inf"), 0.0
    for _ in range(trials):
        f = [rng.gauss(0.0, 1.0) for _ in range(n)]
        if len(set(f)) == 1:
            continue
        v, ee = pairwise_variation(f), edge_energy(f)
        assert v <= n ** 3 * ee + 1e-6          # Poincare inequality
        rq = rayleigh(f)
        assert rq >= 2.0 / n ** 3 - 1e-9        # Rayleigh lower bound
        min_rq = min(min_rq, rq)
        worst = max(worst, v / (n ** 3 * ee))
    print(f"n={n}: min RQ={min_rq:.3e}  bound 2/n^3={2/n**3:.3e}  "
          f"worst vr/(n^3 edge)={worst:.4f} (<=1)")


if __name__ == "__main__":
    for n in (10, 20, 40):
        stress_test(n, trials=20000, seed=n)

